function Config.SkillData2.data_get_skill(slot0)
	if Config.SkillData2.data_get_skill_cache[slot0] == nil then
		if not Config.SkillData2.data_get_skill_table[slot0] then
			return
		end

		if not loadstring(string.format("return %s", slot1))() then
			return
		end

		Config.SkillData2.data_get_skill_cache[slot0] = {
			bid = slot1[1],
			name = slot1[2],
			owner = slot1[3],
			group = slot1[4],
